# Generate TypeScript
lines = []
lines.append("export const BLOG_POSTS: BlogPost[] = [")
for a in articles:
    lines.append("  {")
    lines.append(f'    slug: "{a["slug"]}",')
    lines.append(f'    image: "{a["image"]}",')
    title = a["title"].replace('"', '\\"')
    lines.append(f'    title: "{title}",')
    excerpt = a["excerpt"].replace('"', '\\"')
    lines.append(f'    excerpt: "{excerpt}",')
    lines.append(f'    category: "{a["category"]}",')
    tags_str = ", ".join([f'"{t}"' for t in a["tags"]])
    lines.append(f'    tags: [{tags_str}],')
    lines.append('    author: { name: "Equipo Trackela", role: "Marketing Digital" },')
    lines.append(f'    date: "{a["date"]}",')
    lines.append(f'    readingTime: {a["readingTime"]},')
    if a.get("hero"):
        lines.append('    hero: true,')
    cover = a["cover"]
    lines.append(f'    cover: {{ from: "{cover["from"]}", to: "{cover["to"]}", icon: "{cover["icon"]}" }},')
    lines.append("    body: [")
    for block in a["body"]:
        if block["type"] == "p":
            content = block["content"].replace("\\", "\\\\").replace('"', '\\"').replace('\n', ' ')
            lines.append(f'      {{ type: "p", content: "{content}" }},')
        elif block["type"] == "h2":
            content = block["content"].replace('"', '\\"')
            lines.append(f'      {{ type: "h2", content: "{content}" }},')
        elif block["type"] == "h3":
            content = block["content"].replace('"', '\\"')
            lines.append(f'      {{ type: "h3", content: "{content}" }},')
        elif block["type"] == "ul":
            items = ", ".join([f'"{item.replace(chr(34), chr(92)+chr(34)).replace(chr(92), chr(92)+chr(92))}"' for item in block["items"]])
            lines.append(f'      {{ type: "ul", items: [{items}] }},')
        elif block["type"] == "quote":
            content = block["content"].replace('"', '\\"')
            lines.append(f'      {{ type: "quote", content: "{content}" }},')
        elif block["type"] == "stat":
            label = block["label"].replace('"', '\\"')
            lines.append(f'      {{ type: "stat", value: "{block["value"]}", label: "{label}" }},')
    lines.append("    ],")
    lines.append("  },")
lines.append("];")

with open("/tmp/blog-articles.ts", "w") as f:
    f.write("\n".join(lines))

print(f"Generated {len(articles)} articles")
